import{_ as i,o as t,c as o,aa as n}from"./chunks/framework.BAs_AphD.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","wiki":"en:diary:start"},"headers":[],"relativePath":"en/diary/index.md","filePath":"en/diary/index.md","lastUpdated":1793088561000}'),a={name:"en/diary/index.md"};function l(r,e,c,s,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>The Project Diary module is designed to keep a project diary electronically in compliance with applicable legislation in the Czech Republic and the Slovak Republic. The Buildary.online application (hereinafter referred to as Buildary) is operated in Microsoft&#39;s Azure cloud. Data is protected against unauthorized access, loss, or misuse, and it is guaranteed that it will not leave the territory of the European Union. Thanks to it being cloud-based, information from the construction diary is available to authorized persons at any time and from anywhere with an internet connection.</p><h2 id="legislation" tabindex="-1">Legislation <a class="header-anchor" href="#legislation" aria-label="Permalink to &quot;Legislation&quot;">​</a></h2><p>In accordance with the legislation applicable at the time, questions related to keeping a construction diary in electronic form were carefully discussed with our partner legal advisors as early as 2017. Their legal opinions became the basis for addressing the issue of construction diaries in the Buildary application. Today&#39;s legislation is not only more favorable toward keeping construction diaries in electronic form, but in some cases directly requires them to be maintained electronically.</p><h3 id="czech-republic" tabindex="-1">Czech Republic <a class="header-anchor" href="#czech-republic" aria-label="Permalink to &quot;Czech Republic&quot;">​</a></h3><p>Relevant legislation:</p><ul><li><em>Section 166 of Act No. 283/2021 Coll., the Building Act</em></li><li><em>Annex No. 12 to Decree No. 131/2024 Coll., on Building Documentation</em></li><li><em>Section 5 of Act No. 297/2016 Coll., on Trust Services for Electronic Transactions</em></li><li><em>Section 6 of Act No. 297/2016 Coll., on Trust Services for Electronic Transactions</em></li></ul><h3 id="slovak-republic" tabindex="-1">Slovak Republic <a class="header-anchor" href="#slovak-republic" aria-label="Permalink to &quot;Slovak Republic&quot;">​</a></h3><p>Relevant legislation:</p><ul><li><em>Section 46d of Act No. 50/1976 Coll. on Spatial Planning and Building Regulations (Building Act)</em></li><li><em>Provisions of Section 28 of Decree No. 453/2000 Coll. of the Ministry of the Environment, implementing certain provisions of the Building Act</em></li><li><em>Act No. 272/2016 Coll. on Trust Services for Electronic Transactions in the Internal Market and on Amendments to Certain Acts (Trust Services Act)</em></li><li><em>Act No. 305/2013 Coll. on the Electronic Form of Exercising the Powers of Public Authorities and on Amendments to Certain Acts (e-Government Act)</em></li></ul>',10)])])}const p=i(a,[["render",l]]);export{m as __pageData,p as default};
